#!/usr/bin/env python3
# Generated complete stdlib capsule; imports no host research source.
import sys,types,json
BUNDLED_SOURCE_IDENTITIES={'research_design': {'sha256': 'f18399f81180d8d3637b03eb5f4a7369b5a05a6e31909d50375538006d329f14', 'bytes': 4904}, 'research_protocol_compile': {'sha256': 'b0f88e1aa80198f05e8490b22ce11b1c459dc313abee651407538442ecb925a9', 'bytes': 17386}, 'research_b_transcriptome_registry': {'sha256': 'bd3f65c7ae8400ddd2fc4b485c0904924a3c1bb778b8b38c493ba770254a5887', 'bytes': 39194}, 'pseudobulk_contract': {'sha256': '9728e902e032dd948f8906a5682a42a28d4d2abfc39db96b2265c5670572dca6', 'bytes': 26484}, 'research_b_bulk_limma_inputs': {'sha256': 'affc46025a32d7ad5cfaead4e852e0463608e95a6bb39f72a6f8f47dcf01b549', 'bytes': 20374}}
bundled={}
previous={}
def load_bundled(name,raw):
    previous[name]=sys.modules.get(name)
    module=types.ModuleType(name)
    bundled[name]=module;sys.modules[name]=module
    exec(compile(raw,"bundled-"+name,"exec"),module.__dict__)
    return module
try:
    load_bundled("research_design",bytes.fromhex(""))
    load_bundled("research_protocol_compile",bytes.fromhex(""))
    load_bundled("research_b_transcriptome_registry",bytes.fromhex(""))
    load_bundled("pseudobulk_contract",bytes.fromhex(""))
    pb=bundled["pseudobulk_contract"]
    previous["research_b_counts"]=sys.modules.get("research_b_counts")
    counts=types.ModuleType("research_b_counts");counts.pb=pb
    sys.modules["research_b_counts"]=counts
    component=load_bundled("research_b_bulk_limma_inputs",bytes.fromhex(""))
    family=bundled["research_b_transcriptome_registry"]
finally:
    for name,module in previous.items():
        if module is None:sys.modules.pop(name,None)
        else:sys.modules[name]=module

import os
import zipfile
from pathlib import Path

INPUT_NAMES = ['design_zip','request','expression','source_samples','analysis_samples',
               'features','contrast_lock','source_metadata','resource_alias']
OUTPUT_NAMES = ['expression.tsv','genes.tsv','samples.tsv','decisions.tsv',
                'method-template.json','family-proposal.json','input-preparation.json']


def run():
    inputs = [pb.regular(Path(os.environ['AUTONOMICS_INPUT'+str(index)])) for index in range(9)]
    outputs = [Path(os.environ['AUTONOMICS_OUTPUT'+str(index)]) for index in range(7)]
    pb.require([path.name for path in outputs] == OUTPUT_NAMES and
        len({path.parent.absolute() for path in outputs}) == 1,
        'complete declared bulk outputs in one private directory required')
    pb.require(all(path.is_absolute() and '..' not in path.parts for path in outputs),
        'absolute bulk output paths without parent traversal required')
    parent = outputs[0].parent.absolute()
    pb.require(parent != Path('/') and not any(path.is_symlink() for path in [parent,*parent.parents]),
        'private non-symlink bulk output directory required')
    pb.require(not any(os.path.lexists(path) for path in outputs), 'bulk output exists; refusing overwrite')
    bundle = parent/'.b-bulk-inputs-complete'
    pb.require(not os.path.lexists(bundle), 'complete bulk bundle already exists')
    design, request_path = inputs[:2]
    before_design = pb.sha_file(design)
    before_request = pb.sha_file(request_path)
    raw_request = pb.bounded(request_path)
    pb.require(pb.identity(raw_request)['sha256'] == before_request, 'consumed bulk request bytes differ')
    original = family.compile_protocol(design)
    pb.require(original['source_archive_sha256'] == before_design, 'original archive changed before preparation')
    # All original compiler/governance validation is embedded, not stubbed.
    # The counts shim exposes only the unchanged pseudobulk component API.
    payloads = component.prepare(original, dict(zip(INPUT_NAMES[2:],inputs[2:],strict=True)),
        pb.strict_json(raw_request), design_zip=design)
    pb.require(pb.sha_file(design) == before_design, 'original archive changed during bulk preparation')
    pb.require(pb.sha_file(request_path) == before_request, 'bulk request changed during preparation')
    pb.require(set(payloads) == set(OUTPUT_NAMES), 'complete bulk preparation bundle required')
    component.publish(bundle,payloads)
    # The validated bundle is durable before exposing ports. Link failures
    # leave it for diagnostics and never replace or delete a foreign port.
    for target in outputs:
        os.link(bundle/target.name,target)
    print(json.dumps({'scope':'ACTUAL_SOURCE_BOUND_NORMALIZED_BULK_INPUT_PREPARATION_ONLY',
        'method_executed':False,'scientific_G0_granted':False,'formal_authorized':False}))


if __name__ == '__main__':
    try:
        run()
    except (ValueError,KeyError,OSError,UnicodeError,pb.csv.Error,zipfile.BadZipFile) as error:
        print('BLOCKED: '+str(error),file=sys.stderr)
        raise SystemExit(2)
